:root {
  --bg: #1e1e2f;
  --card-bg: #2a2a40;
  --text: #f0f0f5;
  --text-muted: #b0b0c0;
  --accent: #6c63ff;
  --accent-hover: #7f78ff;
  --accent-active: #5a52e0;
  --focus-ring: #ffb86c;
  --radius: 12px;
  --font: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: var(--font);
  font-size: 16px;
  background: var(--bg);
  color: var(--text);
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  line-height: 1.5;
}

.card {
  background: var(--card-bg);
  border-radius: var(--radius);
  padding: 32px 24px;
  max-width: 600px;
  width: 100%;
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4);
  text-align: center;
}

h1 {
  font-size: 1.75rem;
  font-weight: 700;
  margin-bottom: 8px;
  letter-spacing: -0.02em;
}

.subtitle {
  color: var(--text-muted);
  font-size: 1rem;
  margin-bottom: 24px;
}

.palette {
  display: flex;
  gap: 12px;
  margin-bottom: 28px;
  justify-content: center;
  flex-wrap: wrap;
}

.swatch {
  flex: 1 1 0;
  min-width: 80px;
  max-width: 120px;
  border-radius: var(--radius);
  overflow: hidden;
  position: relative;
  background: #fff;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
  transition: transform 0.15s ease;
}

.swatch:hover {
  transform: translateY(-4px);
}

.swatch-color {
  height: 100px;
  width: 100%;
  display: block;
}

.swatch-info {
  padding: 8px 4px;
  background: var(--card-bg);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
}

.hex-code {
  font-family: 'SF Mono', 'Fira Code', monospace;
  font-size: 0.85rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--text);
  text-transform: uppercase;
}

.lock-btn {
  background: none;
  border: 2px solid var(--text-muted);
  border-radius: 6px;
  color: var(--text-muted);
  font-size: 0.75rem;
  padding: 2px 8px;
  cursor: pointer;
  font-family: var(--font);
  transition: all 0.15s ease;
  display: flex;
  align-items: center;
  gap: 4px;
  line-height: 1.4;
}

.lock-btn:hover {
  border-color: var(--accent-hover);
  color: var(--accent-hover);
  background: rgba(108, 99, 255, 0.1);
}

.lock-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.lock-btn:active {
  transform: scale(0.95);
}

.lock-btn[aria-pressed="true"] {
  border-color: var(--accent);
  color: var(--accent);
  background: rgba(108, 99, 255, 0.15);
}

.lock-icon {
  font-size: 0.85rem;
  display: inline-block;
  width: 1em;
  text-align: center;
}

.generate-btn {
  background: var(--accent);
  color: #fff;
  border: none;
  border-radius: var(--radius);
  padding: 14px 32px;
  font-size: 1.1rem;
  font-weight: 600;
  font-family: var(--font);
  cursor: pointer;
  transition: background 0.15s ease, transform 0.1s ease;
  width: 100%;
  max-width: 320px;
}

.generate-btn:hover {
  background: var(--accent-hover);
}

.generate-btn:focus-visible {
  outline: 2px solid var(--focus-ring);
  outline-offset: 2px;
}

.generate-btn:active {
  background: var(--accent-active);
  transform: scale(0.97);
}

@media (max-width: 480px) {
  .card {
    padding: 24px 16px;
  }
  .swatch {
    min-width: 60px;
  }
  .swatch-color {
    height: 80px;
  }
  .hex-code {
    font-size: 0.75rem;
  }
  .lock-btn {
    font-size: 0.7rem;
    padding: 2px 6px;
  }
}

(function () {
  'use strict';

  const paletteEl = document.getElementById('palette');
  const generateBtn = document.getElementById('generate');

  // State: each swatch has { color: hex string, locked: boolean }
  let swatches = [];

  // --- Color generation helpers ---
  function randomInt(max) {
    return Math.floor(Math.random() * max);
  }

  // Convert HSL to hex
  function hslToHex(h, s, l) {
    s /= 100;
    l /= 100;
    const a = s * Math.min(l, 1 - l);
    const f = (n) => {
      const k = (n + h / 30) % 12;
      const color = l - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
      return Math.round(255 * color).toString(16).padStart(2, '0');
    };
    return `#${f(0)}${f(8)}${f(4)}`.toUpperCase();
  }

  // Generate a harmonious palette: analogous base with slight saturation/lightness variation
  function generatePalette() {
    const baseHue = randomInt(360);
    const baseSat = 55 + randomInt(30); // 55–85
    const baseLight = 45 + randomInt(20); // 45–65

    const offsets = [0, 30, 60, 15, 45]; // analogous spread
    return offsets.map((offset, i) => {
      const hue = (baseHue + offset) % 360;
      const sat = Math.min(90, Math.max(40, baseSat + (i - 2) * 5));
      const light = Math.min(75, Math.max(35, baseLight + (i - 2) * 6));
      return hslToHex(hue, sat, light);
    });
  }

  // --- DOM rendering ---
  function createSwatchElement(index, hex, locked) {
    const wrapper = document.createElement('div');
    wrapper.className = 'swatch';
    wrapper.setAttribute('role', 'listitem');

    const colorDiv = document.createElement('div');
    colorDiv.className = 'swatch-color';
    colorDiv.style.backgroundColor = hex;

    const infoDiv = document.createElement('div');
    infoDiv.className = 'swatch-info';

    const hexSpan = document.createElement('span');
    hexSpan.className = 'hex-code';
    hexSpan.textContent = hex;

    const lockBtn = document.createElement('button');
    lockBtn.type = 'button';
    lockBtn.className = 'lock-btn';
    lockBtn.setAttribute('aria-pressed', locked ? 'true' : 'false');
    lockBtn.setAttribute('aria-label', `${locked ? 'Unlock' : 'Lock'} color ${hex}`);
    lockBtn.dataset.index = index;

    const iconSpan = document.createElement('span');
    iconSpan.className = 'lock-icon';
    iconSpan.setAttribute('aria-hidden', 'true');
    iconSpan.textContent = locked ? '🔒' : '🔓';

    const labelSpan = document.createElement('span');
    labelSpan.textContent = locked ? 'Locked' : 'Lock';

    lockBtn.appendChild(iconSpan);
    lockBtn.appendChild(labelSpan);

    infoDiv.appendChild(hexSpan);
    infoDiv.appendChild(lockBtn);

    wrapper.appendChild(colorDiv);
    wrapper.appendChild(infoDiv);

    return wrapper;
  }

  function render() {
    paletteEl.innerHTML = '';
    swatches.forEach((sw, i) => {
      paletteEl.appendChild(createSwatchElement(i, sw.color, sw.locked));
    });
  }

  // --- State updates ---
  function init() {
    swatches = generatePalette().map((hex) => ({ color: hex, locked: false }));
    render();
  }

  function regenerate() {
    const newColors = generatePalette();
    swatches = swatches.map((sw, i) => ({
      color: sw.locked ? sw.color : newColors[i],
      locked: sw.locked,
    }));
    render();
  }

  function toggleLock(index) {
    if (index >= 0 && index < swatches.length) {
      swatches[index].locked = !swatches[index].locked;
      render();
    }
  }

  // --- Event listeners ---
  generateBtn.addEventListener('click', regenerate);

  paletteEl.addEventListener('click', (event) => {
    const btn = event.target.closest('.lock-btn');
    if (btn && btn.dataset.index !== undefined) {
      toggleLock(Number(btn.dataset.index));
    }
  });

  // Initialize on load
  init();
})();
